$n = 0; $spent = 0.0
foreach ($t in $tests) { $n++
  $body = @{ subject=$t[1]; model="gpt-image-2"; width=1536; height=1024; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  try {
    $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
    if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "[" + $n + "/6] " + $t[0] + " - " + $j.payload.image_url + "  $" + $j.payload.cost_usd }
